CREATE OR REPLACE FUNCTION archive_old_version() RETURNS TRIGGER AS $$
BEGIN
	-- Skip server-side metadata and timestamp only changes
	IF TG_OP = 'UPDATE' AND to_jsonb(OLD) - '{metadata,modified,textsearch_en}'::TEXT[] = to_jsonb(NEW) - '{metadata,modified,textsearch_en}'::TEXT[] THEN
		RETURN NULL;
	END IF;
	EXECUTE format('INSERT INTO %1$I SELECT * FROM jsonb_populate_record(NULL::%1$I, to_jsonb($1))', TG_TABLE_NAME || '_archive') USING OLD;
	RETURN NULL;
END;
$$ LANGUAGE plpgsql

DO $$
DECLARE
	t TEXT;
	c RECORD;
BEGIN
	FOREACH t IN ARRAY ARRAY['ref', 'ext', 'users', 'plugin', 'template'] LOOP
		EXECUTE format('CREATE TABLE IF NOT EXISTS %I (LIKE %I)', t || '_archive', t);
		FOR c IN
			SELECT a.attname, format_type(a.atttypid, a.atttypmod) AS type
			FROM pg_attribute a
			WHERE a.attrelid = t::regclass AND a.attnum > 0 AND NOT a.attisdropped
		LOOP
			EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS %I %s', t || '_archive', c.attname, c.type);
		END LOOP;
		EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (%s, origin, modified)',
			t || '_archive_index', t || '_archive', CASE WHEN t = 'ref' THEN 'url' ELSE 'tag' END);
		EXECUTE format('DROP TRIGGER IF EXISTS archive_old_version ON %I', t);
		EXECUTE format('CREATE TRIGGER archive_old_version AFTER UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION archive_old_version()', t);
	END LOOP;
END;
$$

DO $$
DECLARE t TEXT;
BEGIN
	FOREACH t IN ARRAY ARRAY['ref', 'ext', 'users', 'plugin', 'template'] LOOP
		EXECUTE format('DROP TRIGGER IF EXISTS archive_old_version ON %I', t);
	END LOOP;
END;
$$
